SELECT COUNT(*) FROM promotions_bargain WHERE company_id = #{companyId}
AND item_name LIKE CONCAT('%', #{itemNameContains}, '%')
AND title LIKE CONCAT('%', #{titleContains}, '%')

SELECT bargain_id, company_id, title, ad_pic, item_name, item_pics, item_intro, mkt_price, price, limit_num, order_num, cutdown_rules, cutdown_range, people_range, min_price, begin_time, end_time, share_msg, help_pics, item_id, created, updated FROM promotions_bargain WHERE company_id = #{companyId}
AND item_name LIKE CONCAT('%', #{itemNameContains}, '%')
AND title LIKE CONCAT('%', #{titleContains}, '%')
ORDER BY created DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM promotions_bargain
WHERE company_id = #{companyId}
	AND end_time > #{nowEpochSeconds}
	AND begin_time <= #{nowEpochSeconds}

SELECT bargain_id, company_id, title, ad_pic, item_name, item_pics, item_intro, mkt_price, price,
	limit_num, order_num, cutdown_rules, cutdown_range, people_range, min_price, begin_time, end_time,
	share_msg, help_pics, item_id, created, updated
FROM promotions_bargain
WHERE company_id = #{companyId}
	AND end_time > #{nowEpochSeconds}
	AND begin_time <= #{nowEpochSeconds}
ORDER BY created DESC
LIMIT #{offset}, #{limit}
